INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-kazakhstan-scope-expansion', 'en', 'Kazakhstan''s e-invoicing mandate widens under a new Tax Code', 'From 1 January 2026, Kazakhstan''s e-invoicing mandate expanded under a wholly new Tax Code (Law No. 214-VIII): coverage remains universal for VAT-registered taxpayers, and now extends to roughly a dozen non-VAT-payer categories, including commission agents, customs representatives, medical and pharmaceutical sellers, and law offices. The change lands alongside a lowered VAT registration threshold and a higher standard VAT rate.', '<h3>🇰🇿 Kazakhstan''s e-invoicing mandate widens under a new Tax Code</h3>
<p>Kazakhstan has required e-invoicing through its state IS ESF (Information System of Electronic Invoices) platform for all VAT-registered taxpayers since 1 January 2019 -- a real-time pre-validation clearance model in the same family as Colombia''s and Argentina''s systems. From 1 January 2026, a wholly new Tax Code (Law No. 214-VIII, signed 18 July 2025) recodified and expanded that mandate.</p>
<p>The core VAT-payer requirement remains universal, but the new code brings in roughly a dozen non-VAT-registered categories for the first time: commission agents and freight forwarders, customs representatives and carriers, taxpayers on the simplified tax regime, medical and pharmaceutical sellers, law offices, importers, and participants in the "Virtual Warehouse" goods-traceability module, among others.</p>
<p>The expansion arrives alongside two related changes that widen the population it touches: the VAT registration threshold dropped to 10,000 MRP (roughly KZT 40-43 million in annual turnover, down from about 20,000 MRP), and the standard VAT rate rose to 16%. A companion order (No. 629, 28 October 2025) also introduced new mandatory invoice fields and a buyer-confirmation workflow for corrected or cancelled invoices, alongside a mechanism that ties VAT-credit eligibility directly to active e-invoice confirmation within IS ESF.</p>');
